window.RP_SESSION={"id":"S-114f145201f8","messages":[{"id":"RP-0279413","time":"2026-09-16T01:31:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…허그가 뻬르난떼의 등에서 벗어날때까지 마땅히 풀어볼 이야기도 없겠다, 차라리 이어서 허그의 어린 시절까지 가보도록 할까요.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279414","time":"2026-09-16T01:32:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그의 기억에서 마지막으로 이어지는 가장 어린 시절은…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279415","time":"2026-09-16T01:32:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아마 6? 7? 그정도 까지가 어렴풋이 기억에 남는 것 같습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279416","time":"2026-09-16T01:34:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 여느 (불행하고 불우한 가정에서 태어난 집시) 티플링들처럼 어떻게 일단 태어난 후, 그나마 책임감 있는 부모들을 만나 ‘가델랏’이라는 이름을 받아 한동안은 어찌저찌 가족에 녹아들어 잘 지내왔었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279417","time":"2026-09-16T01:35:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러다가…\n뭐 별거 있겠습니까. 중세에 치안이 안좋은 어디 변방 시골에서 사는 불우한 가정집에게 불행할 이유는 차고도 넘치죠.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279418","time":"2026-09-16T01:38:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"도적이 들던, 부모의 일거리가 적어지던, 어느 몬스터들에게 습격을 받던, 허그의 가정은 불안정해지고 결국 아비인 가버른과 딸인 가델랏, 이 둘만이 남았습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279419","time":"2026-09-16T01:39:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏은 활달하지 못한 아이였습니다.\n사람이 적은 이 작은 마을에서 마땅히 어울릴 친구들도 없었을 뿐더러 지금도 그렇듯, 아픈 것을 싫어했으니 말이죠.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279420","time":"2026-09-16T01:42:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏의 집에 불행이 찾아오고 얼마 뒤,\n가버른은 가델랏을 데리고 마을을 떠났습니다.\n중부와 서부의 사이 어느 곳, 둘은 그곳에서부터 출발하여 근방의 이곳 저곳을 돌아다니며 밥을 얻어먹고, 버린 옷을 주워다 돌려입으면서 삶을 연명해갔습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279421","time":"2026-09-16T01:45:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러다가 결국 질려버리기라도 한 것일까요? 서부 초입의 어느 작은 마을, 가버른은 가델랏에게 근처 주점에서 몰래 훔쳐온 동화 몇닢으로 커다란 막고기 한덩이를 사줬습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279422","time":"2026-09-16T01:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"자신이 재능을 찾은 것 같다느니, 이제 더이상 굶을 걱정은 없다느니.\n가델랏에게 큼직한 고기를 물려준 가버른은 이번엔 자기 몫의 고기를 구해오겠다면서 가델랏을 골목에 숨겨두고 급한 발걸음을 옮겼습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279423","time":"2026-09-16T01:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…이상하다?","characters":["P-6a1a99e98a44"]},{"id":"RP-0279424","time":"2026-09-16T01:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가버른은 돌아오지 않았습니다.\n가델랏을 버린 것일까요?","characters":["P-6a1a99e98a44"]},{"id":"RP-0279425","time":"2026-09-16T01:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 하루…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279426","time":"2026-09-16T01:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이틀…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279427","time":"2026-09-16T01:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…목말라.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279428","time":"2026-09-16T01:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏은 어쩔 수 없이 자리를 옮깁니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279429","time":"2026-09-16T01:48:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"꿀꺽 꿀꺽…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279430","time":"2026-09-16T01:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"어린 나이지만, 당장의 목을 축여야 하니 가델랏은 한 주점의 맥주를 슬~쩍 슈킹!","characters":["P-6a1a99e98a44"]},{"id":"RP-0279431","time":"2026-09-16T01:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-6a1a99e98a44"]},{"id":"RP-0279432","time":"2026-09-16T01:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 민첩 판정 :\n[4] + [3] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0279433","time":"2026-09-16T01:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"물론 이후 주인장에게 걸려 흠씬 얻어맞았습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279434","time":"2026-09-16T01:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 이번에도 어찌저찌 하루하루…\n가버른이 곁에 있던 여태까지와 같이 이번엔 스스로 살아가 보려던 가델랏이었지만","characters":["P-6a1a99e98a44"]},{"id":"RP-0279435","time":"2026-09-16T01:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"역시, 어른이 있고 없고의 차이가 크더군요. 가델랏은 길바닥에 쓰러졌습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279436","time":"2026-09-16T01:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 한 꼬마 티플링의 눈은 스르르르…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279437","time":"2026-09-16T01:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-0279438","time":"2026-09-16T01:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”…어이, 이봐 형씨!! 갑자기 멈추면 어쩌자는거야아!!“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279439","time":"2026-09-16T01:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”허허. 거 참 누가 쫓아오는 것도 아니고! 잠깐만 기다려 보시게.“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279440","time":"2026-09-16T01:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”이러다가 이놈 몸뚱아리를 캠프까지 못 나르면 어쩌려고 그래! 주말에는 사람 밀리는거 몰라? 저번처럼 등신같이 줄서다가 시간 놓치기라도 하면 그쪽이 책임지라고!!“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279441","time":"2026-09-16T02:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”이런, 지난번에 그건 어쩔 수 없었잖나~ 지나간 일은 지나간 대로 두자고.\n게다가 이번엔 나도 나름 신경쓰는 중이니 그때처럼 늦을 일은 없을걸세, 그보다 여기를.“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279442","time":"2026-09-16T02:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”…딱하구먼, 이런데서 낮잠 잤다간 모래먼지만 잔뜩 먹을텐데 말이야.“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279443","time":"2026-09-16T02:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”음…\n여어, 우선은 캠프로 데려가볼까.\n이보게 럼프, 우리 단지에 아직 남은 스튜가 있었지 아마?“”","characters":["P-6a1a99e98a44"]},{"id":"RP-0279444","time":"2026-09-16T02:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 꼬마는 마차에 실려, 어딘가로 향했습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0279445","time":"2026-09-16T02:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0279446","time":"2026-09-16T02:04:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
